begin;
select no_plan();
select has_table('public','route_runs','execuções de rota existem');
select has_table('public','weekly_orders','pedidos semanais existem');
insert into auth.users(id) values('40000000-0000-0000-0000-000000000001'),('40000000-0000-0000-0000-000000000002'),('40000000-0000-0000-0000-000000000003');
insert into public.profiles values('40000000-0000-0000-0000-000000000001','owner'),('40000000-0000-0000-0000-000000000002','driver'),('40000000-0000-0000-0000-000000000003','driver');
insert into public.customers(id,name,address,phone,weekday,position) values('41000000-0000-0000-0000-000000000001','Cliente semanal fictício','Rua original','81999990000',4,1);
insert into public.standing_order_items values('41000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000030',6);
insert into public.customer_prices values('41000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000030',3000);
insert into public.vehicles(id,name) values('42000000-0000-0000-0000-000000000001','Veículo fictício');
select set_config('request.jwt.claim.sub','40000000-0000-0000-0000-000000000001',true);
set local role authenticated;
select is(public.generate_week('2026-11-02','43000000-0000-0000-0000-000000000001')->>'createdRoutes','5','gera cinco rotas');
select throws_ok($$update public.weekly_orders set status='delivered'$$,'42501',null,'escrita direta não contorna bloqueio de rota');
select is(public.generate_week('2026-11-02','43000000-0000-0000-0000-000000000001')->>'createdRoutes','5','mesmo request devolve resultado original');
select is(public.generate_week('2026-11-02',gen_random_uuid())->>'createdRoutes','0','nova geração não duplica rotas');
select is((select count(*) from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001'),1::bigint,'pedido único por cliente/data');
select throws_ok($$select public.generate_week('2026-11-09','43000000-0000-0000-0000-000000000001')$$,'22023','Request conflict','request diferente não reaproveita intenção');
select throws_ok($$select public.generate_week('2026-11-03',gen_random_uuid())$$,'22023','INVALID_INPUT','semana começa segunda');
select is((select count(*) from public.weekly_orders where delivery_date='2026-11-02'),0::bigint,'segunda coleta não cria pedidos');
select is((select price_cents from public.weekly_order_items i join public.weekly_orders o on o.id=i.order_id where o.customer_id='41000000-0000-0000-0000-000000000001'),3000,'preço negociado vira snapshot');
select is((public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001'),1,'[{"productId":"30000000-0000-0000-0000-000000000030","trays":3}]',false,'43000000-0000-0000-0000-000000000002')->>'version')::int,2,'override semanal incrementa versão');
select is((select trays from public.standing_order_items where customer_id='41000000-0000-0000-0000-000000000001'),6,'override não muda padrão');
select throws_ok($$select public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001'),1,'[]',false,gen_random_uuid())$$,'PT409','VERSION_CONFLICT','versão antiga não sobrescreve');
select throws_ok($$select public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001'),2,'[{"productId":"30000000-0000-0000-0000-000000000030","trays":1.5}]',false,gen_random_uuid())$$,'22023','INVALID_INPUT','fração rejeitada no banco');
select public.save_customer('41000000-0000-0000-0000-000000000001',1,'{"name":"Nome futuro","address":"Rua futura","phone":null,"active":true,"weekday":4,"position":1}','[{"productId":"30000000-0000-0000-0000-000000000030","trays":8}]','[{"productId":"30000000-0000-0000-0000-000000000030","priceCents":3500}]',gen_random_uuid());
select public.generate_week('2026-11-02',gen_random_uuid());
select public.generate_week('2026-11-09',gen_random_uuid());
select is((select customer_address from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),'Rua original','cadastro alterado não muda endereço da semana A');
select is((select trays from public.weekly_order_items i join public.weekly_orders o on o.id=i.order_id where o.customer_id='41000000-0000-0000-0000-000000000001' and o.delivery_date='2026-11-05'),3,'regenerar não sobrescreve override');
select is((select trays from public.weekly_order_items i join public.weekly_orders o on o.id=i.order_id where o.customer_id='41000000-0000-0000-0000-000000000001' and o.delivery_date='2026-11-12'),8,'semana B usa novo padrão');
select is((select price_cents from public.weekly_order_items i join public.weekly_orders o on o.id=i.order_id where o.customer_id='41000000-0000-0000-0000-000000000001' and o.delivery_date='2026-11-05'),3000,'preço snapshot da semana A preservado');
select is((select price_cents from public.weekly_order_items i join public.weekly_orders o on o.id=i.order_id where o.customer_id='41000000-0000-0000-0000-000000000001' and o.delivery_date='2026-11-12'),3500,'semana B usa novo preço');
select public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),2,'[]',true,gen_random_uuid());
select is((select trays from public.weekly_order_items i join public.weekly_orders o on o.id=i.order_id where o.customer_id='41000000-0000-0000-0000-000000000001' and o.delivery_date='2026-11-05'),3,'suspensão preserva itens históricos');
select is((select status from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),'suspended','suspensão só na semana escolhida');
select is((select status from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-12'),'planned','outra semana continua planejada');
select public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),3,'[{"productId":"30000000-0000-0000-0000-000000000030","trays":3}]',false,gen_random_uuid());
select public.save_route_run((select id from public.route_runs where service_date='2026-11-05'),4,'40000000-0000-0000-0000-000000000002','42000000-0000-0000-0000-000000000001',(select array_agg(id order by position desc) from public.route_stops where route_id=(select id from public.route_runs where service_date='2026-11-05')),gen_random_uuid());
select is((select kind from public.route_stops where route_id=(select id from public.route_runs where service_date='2026-11-05') and position=1),'arrival','ordenação manual aplica lista completa');
reset role;
update public.route_runs set status='ready' where service_date='2026-11-05';
set local role authenticated;
select throws_ok($$select public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),4,'[]',false,gen_random_uuid())$$,'PT409','ROUTE_LOCKED','rota pronta bloqueia edição');
select is((select version from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),4,'bloqueio não altera versão');
select is(public.reconcile_preparation_request('43000000-0000-0000-0000-000000000099','save_weekly_order')->>'status','closed','reconciliação encerra intenção ausente');
select throws_ok($$select public.save_weekly_order((select id from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000001' and delivery_date='2026-11-05'),4,'[]',false,'43000000-0000-0000-0000-000000000099')$$,'55000','REQUEST_CLOSED','tentativa encerrada não volta a executar');
reset role;
insert into public.customers(id,name,address,weekday,position) values('41000000-0000-0000-0000-000000000002','Novo cliente fictício','Rua nova',4,2);
insert into public.standing_order_items values('41000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000015',1);
set local role authenticated;
select is(public.generate_week('2026-11-02',gen_random_uuid())->>'createdOrders','0','regerar não inclui cliente em rota pronta');
select is(public.generate_week('2026-11-09',gen_random_uuid())->>'createdOrders','1','regerar acrescenta cliente ausente em draft');
select is((select position from public.route_stops s join public.weekly_orders o on o.id=s.order_id where o.customer_id='41000000-0000-0000-0000-000000000001' and o.delivery_date='2026-11-12'),3,'nova parada não muda posição existente');
select is((select position from public.route_stops s join public.weekly_orders o on o.id=s.order_id where o.customer_id='41000000-0000-0000-0000-000000000002' and o.delivery_date='2026-11-12'),6,'nova parada acrescentada ao final deterministicamente');
select is((select count(*) from public.weekly_orders where customer_id='41000000-0000-0000-0000-000000000002' and delivery_date='2026-11-05'),0::bigint,'rota pronta continua sem nova parada');
select throws_ok($$select public.save_route_run((select id from public.route_runs where service_date='2026-11-12'),2,null,null,'{}'::uuid[],gen_random_uuid())$$,'22023','INVALID_INPUT','ordenação deve incluir todas as paradas');
reset role;
select set_config('request.jwt.claim.sub','40000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.get_route_options()$$,'42501','FORBIDDEN','motorista não lê opções administrativas');
select is(public.get_driver_route('2026-11-05')->>'status','ready','motorista lê somente projeção atribuída');
select is(public.get_driver_route('2026-11-02'),'{"available":false}'::jsonb,'sem atribuição mostra indisponibilidade');
select is(public.get_driver_route('2026-11-05')#>>'{stops,2,customerName}','Cliente semanal fictício','projeção usa snapshot original');
select is((select count(*) from public.weekly_orders),0::bigint,'motorista não lê pedidos com valores');
select is((select count(*) from public.weekly_order_items),0::bigint,'motorista não lê preços nos itens');
select is((select count(*) from public.route_stops),0::bigint,'motorista não lê paradas diretamente');
select is(public.get_driver_route('2026-11-05')#>>'{stops,2,items,0,trays}','3','projeção inclui quantidade do snapshot');
select is((select array_agg(key order by key) from jsonb_object_keys(public.get_driver_route('2026-11-05')#>'{stops,2,items,0}')key),array['eggsPerTray','trays']::text[],'item do motorista expõe somente tamanho e quantidade');
select is((select count(*) from public.route_runs),0::bigint,'motorista não lê execuções diretamente');
select ok(not (public.get_driver_route('2026-11-05') @? '$.**.priceCents'),'projeção não contém preço');
select ok(not (public.get_driver_route('2026-11-05') @? '$.**.price_cents'),'projeção não contém coluna de preço');
select throws_ok($$select public.generate_week('2026-11-16',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não gera semana');
reset role;
select set_config('request.jwt.claim.sub','40000000-0000-0000-0000-000000000003',true);
set local role authenticated;
select is(public.get_driver_route('2026-11-05'),'{"available":false}'::jsonb,'outro motorista não vê rota alheia');
select * from finish();
rollback;
